    '« {0} » sera déplacé dans les archives et pourra y être restauré.',
  '„Alle erinnern“ in den Beiträgen wartet so viele Tage nach der Fälligkeit und kann einen Zusatztext anhängen.':
    '« Relancer tout le monde » dans les cotisations attend ce nombre de jours après l’échéance et peut ajouter un texte complémentaire.',
  '„Anlage & Material“ ist im Verein nicht aktiviert.':
    '« Installations & matériel » n’est pas activé dans le club.',
  '„Fällige Beiträge anlegen“ erzeugt für alle zugeordneten Mitglieder die Forderungen, die bis heute fällig sind – nie doppelt.':
    '« Créer les cotisations échues » génère pour tous les membres concernés les créances échues à ce jour – jamais en double.',
  '„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.':
    '« Moi → Paramètres → Inviter » ou, dans l’équipe, « Inviter une personne dans l’équipe » : personnellement par e-mail ou via un lien d’équipe ou un code QR pour s’inscrire soi-même. Pour les liens, tu valides les nouvelles demandes avant que quelqu’un puisse utiliser l’app.',
  '„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.':
    '« Modifier l’équipe → Importer le calendrier » : choisis le fichier CSV du DFBnet, vérifie l’aperçu (nouveau, modifié, inchangé, ignoré) et valide. L’équipe reçoit une notification groupée. Un nouvel import met à jour les reports au lieu de créer les matchs en double. Tu peux annuler l’import dans les 24 heures.',
  '„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.':
    '« Équipe → Effectif → Modifier l’équipe » : ajoute des joueurs depuis la liste du club ou retire-les de l’effectif, change la fonction (joueur, co-entraîneur, encadrant) et le numéro de maillot, désigne le trésorier. En bas, tu règles combien de minutes avant les matchs et entraînements vous vous retrouvez, le lieu de rendez-vous par défaut et les graphies du nom de votre équipe dans le DFBnet. Les co-entraîneurs ont les mêmes droits que l’entraîneur.',
  '„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.':
    '« Équipe → Caisse → Gestion de la caisse ». Tu y trouves sous forme de tuiles : recette/dépense, versements, infliger une amende, liste des boissons, répartition des frais, cotisations, écritures & annulation, trésorier, infos de paiement et vérification de caisse.',
  '„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.':
    '« Équipe → Créer un événement » : entraînement, match ou événement d’équipe. Les matchs reçoivent le type championnat, coupe ou match amical. Pour répéter, choisis « Chaque semaine jusqu’au … » et la date de fin (jusqu’à environ un an). L’app calcule l’heure de rendez-vous d’après les règles de ton équipe ; tu peux la modifier dans chaque événement. Dans l’événement, « Modifier l’événement » te permet de changer un seul événement ou « celui-ci et les suivants ». Avec « Annuler l’événement », l’équipe est prévenue immédiatement.',
  '„Unsicher“ als Antwort erlauben': 'Autoriser « Incertain » comme réponse',
