  'Auch Dubletten werden als neue Einträge angelegt.':
    'Les doublons sont aussi créés comme nouvelles entrées.',
  'auch mehrere auf einmal': 'même plusieurs à la fois',
  'Auch Mitspieler sehen den Grund einer Absage oder Abwesenheit (z. B. verletzt, krank).':
    'Les coéquipiers voient aussi le motif d’un désistement ou d’une absence (p. ex. blessé, malade).',
  'Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.':
    'Même sans publicité, le sponsor reste visible dans l’aperçu.',
  'Audit-Log einsehen': 'Consulter le journal d’audit',
  'Auf der letzten Seite findest du die passenden Schaltflächen.':
    'Sur la dernière page, tu trouveras les boutons correspondants.',
  'Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.':
    'Sur la page d’accueil et sous « Club → Actualités ». Les messages urgents sont en haut et te parviennent aussi par notification push. Avec « J’aime » et les commentaires, tu peux réagir.',
  'Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.':
    'Un paiement a déjà été effectué sur cette créance. Annule d’abord l’écriture dans le livre de caisse.',
  'Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.':
    'Sur chaque sous-page, tu vois ton chemin en haut, par exemple « Équipe › Caisse › Barème des amendes ». Touche un niveau précédent pour y revenir, ou la flèche ronde pour revenir d’un pas. Pour les chemins longs, « … » remplace les niveaux omis ; un toucher les affiche sous forme de liste. La barre du bas reste visible, la rubrique actuelle est mise en évidence.',
  'Auf Konto': 'Sur le compte',
  'auf später verschoben': 'reporté à plus tard',
