  'Aus Datenschutzgründen siehst du nur Zahlen. Den Trainer der Mannschaft kannst du über „Ansprechpartner“ erreichen.':
    'Pour des raisons de protection des données, tu ne vois que des chiffres. Tu peux joindre l’entraîneur de l’équipe via « Contact ».',
