  'Aus diesen Regeln berechnet die App bei jedem neuen Spiel und Training die Treffzeit. Beim einzelnen Termin kannst du sie jederzeit überschreiben. Leer lassen = kein automatisches Treffen.':
    'À partir de ces règles, l’app calcule l’heure de rendez-vous pour chaque nouveau match et entraînement. Dans chaque événement, tu peux la modifier à tout moment. Laisser vide = pas de rendez-vous automatique.',
