  'Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.':
    'Commence le {0}. Tu planifies les effectifs sous Administration → Membres : les équipes de la nouvelle saison y sont marquées « (saison {1}) ».',
  Begründung: 'Motif',
  'Begründung (bei Ablehnung)': 'Motif (en cas de refus)',
  'Begründung für das Storno': 'Motif de l’annulation',
  'Begünstigter Zweck': 'Objet bénéficiaire',
  'Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.':
    'Pour les matchs à l’extérieur et les tournois, l’événement comporte la rubrique « Covoiturage ». Touche « Je conduis » et indique les places libres, ou choisis « Monter » sur une voiture. Qui n’a pas de place touche « Chercher un covoiturage ». Les parents réservent pour leurs enfants.',
  'Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.':
    'Lors de la connexion, nous t’envoyons un code à 6 chiffres par e-mail (valable 10 minutes, utilisable une seule fois). Une application d’authentification est plus sûre – le code par e-mail est l’alternative plus simple.',
  'Bei dir': 'Chez toi',
  'Bei Dubletten': 'En cas de doublons',
  'Bei einer Absage ist ein Grund Pflicht': 'Un motif est obligatoire en cas de désistement',
  'Bei Spielen fehlt der Gegner.': 'L’adversaire manque pour les matchs.',
  'bei Spielen Pflicht': 'obligatoire pour les matchs',
  'Bei Terminen fehlt der Titel.': 'Le titre manque pour les événements.',
  'bei Terminen Pflicht, sonst automatisch': 'obligatoire pour les événements, sinon automatique',
  'Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.':
    'Dans les événements, tu vois la réponse de chaque personne. Les confirmations et désistements valent par enfant.',
  'Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.':
    'Pour les manifestations du club (p. ex. assemblée générale, tournoi), tu peux confirmer, te désister ou choisir « Incertain » – sans motif. Il y a souvent aussi « Bénévoles recherchés » : inscris-toi sur un créneau.',
  beidfüßig: 'ambidextre',
  Beidfüßig: 'Ambidextre',
  'Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.':
    'À la sortie, toutes les affectations d’équipe sont terminées, les rôles retirés et l’accès à l’app bloqué. Les données sont conservées pour les documents du club.',
  'Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).':
    'Lors de l’enregistrement d’une recette, tu choisis le sponsor (Club → Sponsors).',
  'Beim Eigentor des Gegners gibt es keinen Torschützen.':
    'Pour un but contre son camp de l’adversaire, il n’y a pas de buteur.',
  'Beim Kassenwart oder Trainerteam': 'Auprès du trésorier ou du staff d’entraîneurs',
  'Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.':
    'À la suppression, les désistements automatiques sont annulés. Pour les équipes avec confirmation/désistement actifs, la réponse est ensuite de nouveau en attente.',
  'Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.':
    'Lors de la planification d’une manifestation, tu choisis le groupe en haut (« Tout le club », une section …). Avec « Choisir des équipes ou des personnes », tu invites de façon ciblée : coche des équipes dans la fenêtre ou recherche des personnes. La sélection apparaît sous forme de puces ; avec « × », tu retires quelqu’un. Seules les personnes invitées sont notifiées. Tu ne peux inviter des personnes individuelles qu’avec le droit sur la liste des membres.',
  'Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.':
    'Au démarrage et après une minute en arrière-plan, l’app demande Face ID, l’empreinte digitale ou le code de l’appareil. Ce réglage ne s’applique qu’à cet appareil.',
