  'Das Kürzel „{0}“ ist in dieser Saison vergeben.':
    'L’abréviation « {0} » est déjà prise cette saison.',
  'Das Kürzel (2 bis 4 Zeichen, z. B. „SGW“) steht groß im Plakat der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist. Die Vereinsadministration ändert es unter „Verwaltung → Verein & Design“, mit Vorschau. Die Vibration bei Auswahl und Bestätigung schaltest du auf dem Handy unter „Ich → Konto & Einstellungen → Vibration“ aus; bei eingestellter „Bewegung reduzieren“ des Geräts bleiben auch die Animationen aus.':
    'L’abréviation (2 à 4 caractères, p. ex. « SGW ») figure en grand sur l’affiche de la page d’accueil et remplace l’écusson tant qu’aucun logo n’est envoyé. L’administration du club la modifie sous « Administration → Club & design », avec aperçu. Tu désactives la vibration lors de la sélection et de la confirmation sur ton téléphone sous « Moi → Compte & paramètres → Vibration » ; si « Réduire les animations » est activé sur l’appareil, les animations sont aussi désactivées.',
  'Das Kürzel besteht aus 2 bis 4 Buchstaben oder Ziffern.':
    'L’abréviation comporte 2 à 4 lettres ou chiffres.',
  'Das Kürzel steht groß im Plakat auf der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist.':
    'L’abréviation figure en grand sur l’affiche de la page d’accueil et remplace l’écusson tant qu’aucun logo n’est envoyé.',
