  'Das sind alle Termine.': 'Ce sont tous les événements.',
  'Das sind optionale Funktionen, die dein Verein einschalten kann: Fundbüro & Marktplatz für Gesuchtes und Gefundenes, ein kleines Forum für wenige Themen und Vereinswissen mit Artikeln wie „Wo gibt es den Schlüssel?“. Sie erscheinen nur, wenn sie aktiv sind.':
    'Ce sont des fonctions facultatives que ton club peut activer : objets trouvés & petites annonces pour ce qui est cherché ou trouvé, un petit forum pour quelques sujets et le savoir du club avec des articles comme « Où trouver la clé ? ». Elles n’apparaissent que si elles sont actives.',
