  'Das Trainerteam sieht Grund und Freitext immer, Eltern die Gründe ihres Kindes. Ob auch die Mitspieler die Gründe sehen, stellt das Trainerteam in „Mannschaft bearbeiten“ ein („Abwesenheitsgründe für die Mannschaft sichtbar“, Standard aus).':
    'Le staff d’entraîneurs voit toujours le motif et le texte libre, les parents voient les motifs de leur enfant. Si les coéquipiers voient aussi les motifs, le staff le règle dans « Modifier l’équipe » (« Motifs d’absence visibles pour l’équipe », désactivé par défaut).',
