  'Der Kassenbericht': 'Le rapport de caisse',
  'Der Kassenwart bucht Einnahmen, Ausgaben und Einzahlungen und pflegt den Strafenkatalog – gemeinsam mit dem Trainerteam. Infrage kommen Mitglieder mit eigenem Login und Eltern.':
    'Le trésorier enregistre recettes, dépenses et versements et gère le barème des amendes – avec le staff d’entraîneurs. Peuvent être désignés les membres ayant leur propre identifiant et les parents.',
  'Der Kassenwart bucht und verwaltet Beiträge, Kassenprüfer sehen alles und prüfen am Jahresende. Optional – Rollen lassen sich später vergeben.':
    'Le trésorier enregistre et gère les cotisations, les vérificateurs de caisse voient tout et contrôlent en fin d’année. Facultatif – les rôles peuvent être attribués plus tard.',
