  'Der Sponsor': 'Le sponsor',
  'Der Standard-Treffpunkt und die Minuten vor Beginn werden bei neuen Terminen vorbelegt.':
    'Le lieu de rendez-vous par défaut et les minutes avant le début sont préremplis pour les nouveaux événements.',
