  'Die gesetzliche Aufbewahrungsfrist läuft noch.': 'Le délai légal de conservation court encore.',
  'Die Hauptkasse kann nicht stillgelegt werden. Lege zuerst eine andere Kasse als Hauptkasse fest.':
    'La caisse principale ne peut pas être désactivée. Définis d’abord une autre caisse comme caisse principale.',
  'Die Hauptkasse nimmt Buchungen ohne Abteilungsbezug auf und kann nicht stillgelegt werden. Lege eine andere Kasse als Hauptkasse fest, um zu wechseln.':
    'La caisse principale reçoit les écritures sans rattachement à une section et ne peut pas être désactivée. Définis une autre caisse comme caisse principale pour changer.',
  'Die importierten Einträge wurden wieder entfernt, aktualisierte Werte zurückgesetzt.':
    'Les entrées importées ont été retirées, les valeurs mises à jour rétablies.',
