  'Die Kassenprüfung machen Kassenprüfer. Hier siehst du die abgegebenen Prüfberichte.':
    'La vérification de caisse est faite par les vérificateurs de caisse. Tu vois ici les rapports de vérification remis.',
  'Die Kassenstatistik sieht die Mannschaft.': 'L’équipe voit les statistiques de caisse.',
  'Die Kassenverwaltung ist für Kassenwart und Trainerteam.':
    'La gestion de la caisse est réservée au trésorier et au staff d’entraîneurs.',
  'Die Kategorie': 'La catégorie',
  'Die Kategorie „{0}“ gilt für Ausgaben.': 'La catégorie « {0} » s’applique aux dépenses.',
  'Die Kategorie „{0}“ gilt für Einnahmen.': 'La catégorie « {0} » s’applique aux recettes.',
  'Die Kategorie ist archiviert.': 'La catégorie est archivée.',
  'Die Kennzahl zeigt auf einen Blick, was dort los ist: bei Terminen und Veranstaltungen das Datum des nächsten (TT.MM.), beim Kader die Zahl der Spieler, bei der Statistik die Bilanz (Siege-Remis-Niederlagen), bei der Kasse den Kassenstand, bei Aufgaben und Umfragen die offenen, bei News, Dokumenten und Wissen die neuen, beim Spielplan die Spiele der Woche, bei Helfern die freien Plätze. Orange heißt: Hier wartet etwas auf dich. Kacheln ohne sinnvolle Zahl haben keine Kennzahl.':
    'L’indicateur montre d’un coup d’œil ce qui s’y passe : pour les événements et manifestations, la date du prochain (JJ.MM.), pour l’effectif le nombre de joueurs, pour les statistiques le bilan (victoires-nuls-défaites), pour la caisse le solde, pour les tâches et sondages ceux qui sont ouverts, pour les actualités, documents et savoir les nouveautés, pour le calendrier les matchs de la semaine, pour les bénévoles les places libres. Orange signifie : quelque chose t’attend ici. Les tuiles sans chiffre pertinent n’ont pas d’indicateur.',
  'Die kleine Zeile unter dem Namen einer Kachel zeigt, was für dich gerade wichtig ist, z. B. „Du hast 12,50 € offen“, „Antwort fehlt“ oder „2 zur Freigabe“. Die Farbe verstärkt den Text: Orange heißt, es gibt etwas zu tun. Was du nicht sehen darfst, wird nicht angezeigt.':
    'La petite ligne sous le nom d’une tuile montre ce qui est important pour toi en ce moment, p. ex. « Tu as 12,50 € en attente », « Réponse manquante » ou « 2 à valider ». La couleur renforce le texte : orange signifie qu’il y a quelque chose à faire. Ce que tu n’as pas le droit de voir n’est pas affiché.',
  'Die Kostenstelle': 'Le centre de coûts',
  'Die Lesebestätigung sehen Verfasser und Freigebende.':
    'L’accusé de lecture est visible par l’auteur et les validateurs.',
