  'Die Vereinskasse einrichten': 'Configurer la caisse du club',
  'Die Vereinskasse führt der Kassenwart (Verein).':
    'La caisse du club est tenue par le trésorier (club).',
  'Die Vereinskasse führt nur die Kassenführung.':
    'Seule la direction de la caisse tient la caisse du club.',
  'Die Vereinskasse ist nicht aktiviert.': 'La caisse du club n’est pas activée.',
  'Die Vereinskasse ist von den Mannschaftskassen getrennt und liegt unter „Verein → Vereinskasse“ (wenn das Modul aktiv ist). Der Kassenwart (Verein) legt Konten mit Anfangsbestand an, bucht Einnahmen und Ausgaben mit Kategorie, optionaler Kostenstelle, Belegnummer und Belegfoto und bucht um zwischen Konten. Buchungen werden nie gelöscht, sondern mit Begründung storniert. Die Kategorien gehören zu den vier steuerlichen Bereichen (ideell, Vermögensverwaltung, Zweckbetrieb, wirtschaftlicher Geschäftsbetrieb). Kassenprüfer lesen alles, buchen aber nicht. Wer außerdem einsehen darf (z. B. der Vorstand), stellt die Vereinsadministration unter „Einrichtung“ ein.':
    'La caisse du club est distincte des caisses d’équipe et se trouve sous « Club → Caisse du club » (si le module est actif). Le trésorier (club) crée des comptes avec solde initial, enregistre recettes et dépenses avec catégorie, centre de coûts facultatif, numéro et photo de justificatif, et fait des virements entre comptes. Les écritures ne sont jamais supprimées, mais annulées avec un motif. Les catégories relèvent des quatre domaines fiscaux (non lucratif, gestion de patrimoine, activité d’intérêt général, activité économique). Les vérificateurs de caisse lisent tout, mais n’enregistrent pas. Qui peut en outre consulter (p. ex. le comité directeur) est réglé par l’administration du club sous « Configuration ».',
  'Die Vereinskasse sehen nur Kassenführung und Prüfer.':
    'Seuls la direction de la caisse et les vérificateurs voient la caisse du club.',
  'Die Verwaltung ist für Vorstand, Leitung und Administration.':
    'L’administration est réservée au comité directeur, à la direction et à l’administration.',
