  'DU ALS TRAINER': 'TOI EN TANT QU’ENTRAÎNEUR',
  'Du bestimmst in deinem Profil, wer deine Kontaktdaten sehen darf. Trainer sehen nur die Daten ihrer Mannschaft.':
    'Dans ton profil, tu décides qui peut voir tes coordonnées. Les entraîneurs ne voient que les données de leur équipe.',
