  'Du kannst nur Zahlungen für dich oder deine Kinder melden.':
    'Tu ne peux déclarer des paiements que pour toi ou tes enfants.',
  'Du kannst Spieler abstellen': 'Tu peux mettre des joueurs à disposition',
  'Du kannst weitere Anlagen ergänzen und alles später in der Verwaltung ändern.':
    'Tu peux ajouter d’autres installations et tout modifier plus tard dans l’administration.',
  'Du siehst den Vereinsüberblick, alle Vereinstermine und News, kannst bei Veranstaltungen zu- oder absagen und dich als Helfer eintragen. Eigene News kannst du schreiben; sie werden nach Freigabe durch den Vorstand veröffentlicht.':
    'Tu vois l’aperçu du club, tous les événements et actualités du club, peux confirmer ou te désister pour les manifestations et t’inscrire comme bénévole. Tu peux rédiger tes propres actualités ; elles sont publiées après validation par le comité directeur.',
