  'Ein geänderter Betrag gilt für künftige Beiträge; bereits erzeugte Forderungen bleiben unverändert. Der Rhythmus lässt sich nicht ändern.':
    'Un montant modifié vaut pour les cotisations futures ; les créances déjà générées restent inchangées. La périodicité ne peut pas être modifiée.',
