    'Une année ne peut être clôturée qu’après sa fin.',
  'Ein kurzer Willkommenstext erscheint im Team-Tab – zum Beispiel zu Kleidung, Treffpunkten und Regeln.':
    'Un court texte de bienvenue apparaît dans l’onglet Équipe – par exemple sur la tenue, les lieux de rendez-vous et les règles.',
  'Ein Mannschafts-Link (oder QR-Code als Aushang) lässt neue Spieler und Eltern eine Beitrittsanfrage stellen. Du gibst jede Anfrage frei. Ein neuer Link macht den alten ungültig.':
    'Un lien d’équipe (ou un code QR en affichage) permet aux nouveaux joueurs et aux parents de faire une demande d’adhésion. Tu valides chaque demande. Un nouveau lien rend l’ancien invalide.',
  'ein Platz bleibt frei': 'une place reste libre',
  'Ein Platz der Formation ist doppelt besetzt.': 'Un poste de la formation est occupé deux fois.',
  'Ein Spieler steht doppelt in der Aufstellung.':
    'Un joueur figure deux fois dans la composition.',
  'Ein Sponsor passt nur zu einer Einnahme.': 'Un sponsor ne peut être associé qu’à une recette.',
  'Ein Team': 'Une équipe',
  'Ein zusätzlicher Schutz: Nach dem Passwort fragt die App einen Code ab – aus einer Authenticator-App oder per E-Mail (6 Stellen, 10 Minuten gültig, nur einmal nutzbar). Du richtest ihn unter „Ich → Konto & Einstellungen“ ein. Pflicht ist er nur für das Administrationskonto, wenn der Verein es verlangt.':
    'Une protection supplémentaire : après le mot de passe, l’app demande un code – issu d’une application d’authentification ou envoyé par e-mail (6 chiffres, valable 10 minutes, utilisable une seule fois). Tu le configures sous « Moi → Compte & paramètres ». Il n’est obligatoire que pour le compte d’administration, si le club l’exige.',
