  Einzahlungen: 'Versements',
  'Einzeln unter „Mitglieder → Mitglied anlegen“ oder per Import aus Excel oder CSV („Importieren“): Bereich wählen, Vorlage laden, Datei hochladen, Spalten zuordnen, Vorschau prüfen (neu, aktualisiert, Dublette, Fehler), bei Dubletten überspringen, aktualisieren oder neu anlegen. Der Import wird ganz oder gar nicht übernommen und lässt sich 24 Stunden lang rückgängig machen. Austritte beenden Mannschaftszugehörigkeiten und sperren den App-Zugang. In der Mitgliederliste filterst du nach Rolle, Trainerteam, individuellen Rechten oder fehlendem App-Zugang.':
    'Individuellement sous « Membres → Créer un membre » ou par import depuis Excel ou CSV (« Importer ») : choisir le domaine, charger le modèle, envoyer le fichier, affecter les colonnes, vérifier l’aperçu (nouveau, mis à jour, doublon, erreur), pour les doublons ignorer, mettre à jour ou créer. L’import est repris en totalité ou pas du tout et peut être annulé pendant 24 heures. Les sorties terminent les appartenances aux équipes et bloquent l’accès à l’app. Dans la liste des membres, tu filtres par rôle, staff d’entraîneurs, droits individuels ou accès à l’app manquant.',
