  'Es erscheint oben in der App bei allen Mitgliedern. Ohne Logo zeigt die App ein Wappen mit dem Kürzel.':
    'Il apparaît en haut de l’app chez tous les membres. Sans logo, l’app affiche un écusson avec l’abréviation.',
  'Es fehlen {0} aktive Schiedsrichter': 'Il manque {0} arbitres actifs',
  'Es fehlen zugeordnete Pflichtfelder.': 'Des champs obligatoires affectés manquent.',
