  'Gelöscht – lässt sich wiederherstellen': 'Supprimé – peut être restauré',
  'Gelöschte Einträge liegen hier und lassen sich wiederherstellen. Endgültig gelöscht wird nie automatisch, sondern nur auf deinen Anstoß.':
    'Les entrées supprimées sont ici et peuvent être restaurées. Rien n’est jamais supprimé définitivement automatiquement, seulement à ton initiative.',
  'Gelöschte Rollen': 'Rôles supprimés',
  'Gelöschte Rollen lassen sich wiederherstellen.': 'Les rôles supprimés peuvent être restaurés.',
  'Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.':
    'Les articles de savoir, exercices, tâches, sponsors, documents supprimés et le matériel réformé vont dans les archives ; pour les documents, le fichier est conservé jusqu’au nettoyage des archives. Le staff d’entraîneurs ouvre les archives de son équipe sous « Équipe → Archives » (tâches et documents supprimés, restauration). L’administration ouvre toutes les archives sous « Administration → Abonnement & contrôle → Archives » : tu y restaures une entrée avec « Restaurer ». Si son nom est entre-temps déjà pris, l’app te demande un nouveau nom. Rien n’est jamais supprimé définitivement automatiquement : « Nettoyer » retire ce qui dépasse le délai standard (actuellement 2 ans), « Vider les archives » supprime tout ; les deux seulement à ton initiative et avec confirmation. « Exporter les archives » enregistre toutes les entrées archivées dans un fichier.',
