  'Hallo! Wir nutzen Clubroof für {0}: Termine, Zu- und Absagen und alle Infos an einem Ort. Hier kommst du in die Mannschaft: {1}':
    'Salut ! Nous utilisons Clubroof pour {0} : événements, confirmations et désistements et toutes les infos au même endroit. Ici, tu rejoins l’équipe : {1}',
  'Hält den Kassenstand von heute fest – z. B. nach der Kassenprüfung oder zum Saisonende. Der Abschluss erscheint auch im Kassenbericht. Beim Saisonwechsel geht die Kasse automatisch auf die neue Mannschaft über.':
    'Consigne le solde de caisse d’aujourd’hui – p. ex. après la vérification de caisse ou en fin de saison. La clôture apparaît aussi dans le rapport de caisse. Lors du changement de saison, la caisse passe automatiquement à la nouvelle équipe.',
