  'Jede Änderung setzt die Freigabe der Vorlage zurück.':
    'Chaque modification réinitialise la validation du modèle.',
  'Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.':
    'Chaque caisse a ses propres comptes, cotisations et analyse. Sans affectation, une section passe par la caisse principale. La clôture annuelle vaut toujours pour tout le club.',
  'Jede Leitung sieht nur Daten ihrer Abteilung':
    'Chaque direction ne voit que les données de sa section',
  'Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.':
    'Chaque équipe fixe jusqu’à quand on peut confirmer ou se désister. Le compte à rebours figure sur l’événement (« Délai : encore 2 jours »). Ensuite, ta réponse reste visible (cadenas « Délai expiré »), seul ton staff d’entraîneurs peut la modifier.',
  'Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt':
    'Chaque personne confirme ou se désiste – l’entraîneur voit qui manque encore',
  'Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.':
    'Chaque ligne est verte (nouveau), bleue (mis à jour), jaune (doublon) ou rouge (erreur). Les lignes désélectionnées ne sont pas reprises.',
  'Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.':
    'Chaque joueur garde son numéro ; il apparaît dans l’effectif et dans la composition.',
  'Jeder Spieler der Startelf braucht einen Platz der Formation.':
    'Chaque joueur du onze de départ a besoin d’un poste de la formation.',
  'Jedes Feld kann nur einer Spalte zugeordnet werden.':
    'Chaque champ ne peut être affecté qu’à une seule colonne.',
  'Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.':
    'Chaque membre soumet sous « Club → Soumettre un remboursement » des frais avec justificatif (photo) ou des frais de déplacement – pour les frais de déplacement, l’app calcule à partir des kilomètres (30 centimes par km). Le trésorier voit les remboursements sous « Caisse du club → Écriture → Remboursements de frais », approuve ou refuse en motivant, puis rembourse : une dépense est alors créée dans le livre de caisse. Tu reçois une notification à chaque étape. Un remboursement effectué ne peut pas être annulé.',
