  Kassen: 'Caisses',
  'Kassen legt die Kassenführung des ganzen Vereins an.':
    'Les caisses sont créées par la direction de la caisse de tout le club.',
  'Kassenbericht {0} {1}-{2}': 'Rapport de caisse {0} {1}-{2}',
  Kassenbuch: 'Livre de caisse',
  'Kassenbuch öffnen': 'Ouvrir le livre de caisse',
  'Kassenbuchung erfasst': 'Écriture de caisse saisie',
  Kassenprüfer: 'Vérificateur de caisse',
  'Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.':
    'Les vérificateurs de caisse commencent sous « Caisse du club → Analyse → Vérification de caisse » une vérification pour une année – pour tout le club ou seulement leur caisse. L’app tire au hasard des échantillons à la demande ; chaque écriture est cochée ou contestée avec un motif, tu vois directement le justificatif. S’y ajoutent des notes libres. Quand tous les échantillons sont traités, tu remets le rapport de vérification avec ton résultat ; ensuite il n’est plus modifiable et sert de base à la décharge. La direction de la caisse voit les rapports remis (aussi en PDF ou CSV). Les vérificateurs n’enregistrent pas d’écritures, le trésorier ne vérifie pas.',
  Kassenprüfung: 'Vérification de caisse',
  'Kassenprüfung {0} begonnen': 'Vérification de caisse {0} commencée',
  'Kassenprüfung {0}: {1} Stichproben gezogen':
    'Vérification de caisse {0} : {1} échantillons tirés',
  'Kassenprüfung {0}: Beanstandung vermerkt': 'Vérification de caisse {0} : contestation consignée',
  'Kassenprüfung {0}: Prüfbericht abgegeben':
    'Vérification de caisse {0} : rapport de vérification remis',
  Kassenprüfungen: 'Vérifications de caisse',
