  'Kassenstand gesamt': 'Solde de caisse total',
  'Kassenstand nicht sichtbar': 'Solde de caisse non visible',
  'Kassenstand seit Saisonbeginn': 'Solde de caisse depuis le début de la saison',
  'Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft. Die Beträge der einzelnen Personen zeigst du nur, wenn ihr das wollt – sonst sieht jeder nur die eigenen.':
    'Le solde de caisse, les recettes et les dépenses sont toujours visibles pour toute l’équipe. Tu n’affiches les montants des personnes individuelles que si vous le souhaitez – sinon chacun ne voit que les siens.',
