  'Kurzfristige Absage: {0} {1}': 'Désistement de dernière minute : {0} {1}',
  'Kurzfristige Absagen und dringende Vereinsnews erreichen dich unabhängig von diesen Einstellungen – auch in der Ruhezeit.':
    'Les désistements de dernière minute et les actualités urgentes du club te parviennent indépendamment de ces réglages – même pendant la plage de repos.',
  Kurzname: 'Nom court',
  'Kurzname (Kopfzeile, Wappen)': 'Nom court (en-tête, écusson)',
  'Kurztext (optional)': 'Texte court (facultatif)',
  'Lade Daten als Excel- oder CSV-Datei herunter. Du siehst nur, wofür du Rechte hast; jeder Export wird im Protokoll des Vereins festgehalten.':
    'Télécharge des données sous forme de fichier Excel ou CSV. Tu ne vois que ce pour quoi tu as des droits ; chaque export est consigné dans le journal du club.',
  'Lade den Kontoauszug als CSV-Datei deiner Bank hoch. Erkannt werden Buchungstag, Betrag, Name und Verwendungszweck. Zugeordnet wird per Mitgliedsnummer oder Name, wenn der Betrag genau zu einer offenen Forderung passt. Du siehst alles vorher.':
    'Envoie le relevé de compte au format CSV de ta banque. Date d’écriture, montant, nom et motif sont reconnus. L’affectation se fait par numéro de membre ou nom lorsque le montant correspond exactement à une créance ouverte. Tu vois tout avant.',
  'Lade den Spielplan als CSV-Datei aus dem DFBnet (Meisterschaft › Vereinsspielplan bzw. Mannschaftsspielplan › Export). Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung. Ein erneuter Import aktualisiert bestehende Spiele, statt sie doppelt anzulegen.':
    'Envoie le calendrier au format CSV depuis le DFBnet (Championnat › Calendrier du club ou calendrier de l’équipe › Export). Tu vois d’abord un aperçu – rien n’est repris avant ta confirmation. Un nouvel import met à jour les matchs existants au lieu de les créer en double.',
