  Mi: 'Me',
  Mich: 'Moi',
  'Minderjährig ohne Elternteil und ohne E-Mail – später zuordnen.':
    'Mineur sans parent et sans e-mail – à affecter plus tard.',
  'Mindestens 10 Zeichen – am besten ein kurzer Satz.':
    'Au moins 10 caractères – idéalement une courte phrase.',
  'Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.':
    'Au moins 10 caractères. Une suite de mots ou une phrase est plus sûre et plus facile à retenir qu’un mot de passe court avec des caractères spéciaux.',
  'Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.':
    'Au moins une personne importée a déjà un compte. L’import ne peut plus être annulé.',
  'Mindestens zwei Buchstaben eingeben.': 'Saisir au moins deux lettres.',
  'Mini-Forum': 'Mini-forum',
  'Mit Ablaufdatum': 'Avec date d’expiration',
  'Mit App-Zugang': 'Avec accès à l’app',
  'Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.':
    'Au démarrage, {0} devient la saison en cours. Les caisses d’équipe, documents d’équipe et événements futurs passent aux nouvelles équipes. Les affectations et tâches de l’ancienne saison prennent fin. Cette action est irréversible.',
  'Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.':
    'Avec les flèches, tu décales la date d’un jour. Si tu touches la date elle-même, un calendrier s’ouvre : balaye ou touche les flèches pour changer de mois, touche un jour pour le choisir ou sélectionne « Aujourd’hui ». Les jours non autorisés sont grisés.',
  'Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.':
    'Avec les graphies du DFBnet, l’import du calendrier affecte correctement les matchs.',
  'Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.':
    'Avec l’adresse postale, Clubroof remplit les reçus de dons ; le fuseau horaire détermine les délais et horaires des événements.',
  'Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.':
    'Avec la connexion à deux facteurs, chaque nouvelle connexion nécessite en plus un code. Nous la recommandons pour le compte d’administration.',
  'Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.':
    'Un compte existe déjà avec cette adresse e-mail. Merci de te connecter ou d’utiliser « Mot de passe oublié ».',
  'Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.':
    'Avec un lien ou un code d’invitation (aussi par scan de code QR), tu rejoins ton club – le club est ensuite mémorisé sur cet appareil. Si tu as déjà un compte, connecte-toi avec e-mail et mot de passe (« Afficher » rend le mot de passe visible). Tu configures un nouveau club avec le code de configuration (format CR-XXXX-XXXX) que tu reçois de Clubroof après réception du paiement ; il n’est valable qu’une fois.',
  'Mit Face ID oder Fingerabdruck entsperren': 'Déverrouiller avec Face ID ou l’empreinte digitale',
  'Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.':
    'Avec des horaires d’entraînement fixes, les événements sont aussitôt dans le calendrier, et confirmations et désistements fonctionnent dès le premier jour.',
