  'Mitglieder importiert: {0} neu{1}': 'Membres importés : {0} nouveaux{1}',
  'Mitglieder melden Zahlungen in ihrem Konto. Du siehst sie in der Kassenverwaltung unter „Zahlungsmeldungen“ und bestätigst mit „Eingegangen“ – dann wird die Einzahlung gebucht – oder „Nicht gefunden“.':
    'Les membres déclarent leurs paiements dans leur compte. Tu les vois dans la gestion de la caisse sous « Déclarations de paiement » et confirmes avec « Reçu » – le versement est alors enregistré – ou « Introuvable ».',
  'Mitglieder ohne Geburtsdatum werden bei der Jugend-Regel übersprungen und bleiben ohne Beitragsart; Mitglieder mit laufender Beitragsart werden nie verändert.':
    'Les membres sans date de naissance sont ignorés par la règle jeunes et restent sans type de cotisation ; les membres avec un type de cotisation en cours ne sont jamais modifiés.',
