  'Nach Beginn eines Termins hakst du ab, wer wirklich da war (vorausgewählt sind die Zusagen). Danach zählt für Trainingsquote und Statistik die Anwesenheit statt der Zusage. Auf Start erinnert dich ein Hinweis an Trainings der letzten Woche.':
    'Après le début d’un événement, tu coches qui était réellement présent (les confirmations sont présélectionnées). Ensuite, pour le taux de participation et les statistiques, la présence compte à la place de la confirmation. Sur l’accueil, une remarque te rappelle les entraînements de la semaine dernière.',
