  'Name, Kontaktdaten, Mannschaftszugehörigkeit, Zu- und Absagen sowie – nur für Berechtigte – Kassendaten. Gründe für Abwesenheiten sind nur für Trainer und Verantwortliche sichtbar.':
    'Nom, coordonnées, appartenance à une équipe, confirmations et désistements ainsi que – uniquement pour les personnes autorisées – données de caisse. Les motifs d’absence ne sont visibles que pour les entraîneurs et responsables.',
