  Nein: 'Non',
  'Nein. In der Ruhezeit (22 bis 7 Uhr) gibt es keine Push-Nachrichten außer bei dringenden Meldungen. Alles andere wartet bis zum Morgen.':
    'Non. Pendant la plage de repos (de 22 h à 7 h), il n’y a pas de notifications push, sauf pour les messages urgents. Tout le reste attend le matin.',
  'Nein. Trage eine Abwesenheit ein (Urlaub, Verletzt, Krank, Sonstiges). Alle betroffenen Termine werden automatisch abgesagt, das Trainerteam sieht es sofort. Löschst du die Abwesenheit, werden die automatischen Absagen zurückgenommen.':
    'Non. Saisis une absence (vacances, blessé, malade, autre). Tous les événements concernés sont automatiquement décommandés, le staff d’entraîneurs le voit immédiatement. Si tu supprimes l’absence, les désistements automatiques sont annulés.',
