  'Nur Admins: Verwaltung › Rollen und Rechte › „Neue Rolle“. Du gibst Name, Beschreibung und den Geltungsbereich (Verein, Abteilung, Mannschaft) an und wählst die Rechte in Klartext; mit „Start als Kopie von“ übernimmst du eine vorhandene Rolle. Sensible Rechte tragen ein Schloss. Vereinsweite Rechte (Verein, Vereinskasse, Mitglieder) gibt es nur in vereinsweiten Rollen, und du kannst nur Rechte vergeben, die du selbst hast. Standardrollen sind geschützt – dort gibt es „Kopie anpassen“. Gelöschte Rollen lassen sich wiederherstellen; Personen stellst du beim Löschen auf eine andere Rolle um. In der Übersicht zeigen die Reiter Rollen, Personen und Matrix den Stand; bei einer Person zeigt „Was darf diese Person?“ jedes Recht mit seiner Quelle.':
    'Admins uniquement : Administration › Rôles et droits › « Nouveau rôle ». Tu indiques nom, description et périmètre (club, section, équipe) et choisis les droits en clair ; avec « Démarrer comme copie de », tu reprends un rôle existant. Les droits sensibles portent un cadenas. Les droits à l’échelle du club (club, caisse du club, membres) n’existent que dans des rôles à l’échelle du club, et tu ne peux attribuer que des droits que tu possèdes toi-même. Les rôles standard sont protégés – il y a là « Adapter la copie ». Les rôles supprimés peuvent être restaurés ; lors de la suppression, tu bascules les personnes vers un autre rôle. Dans l’aperçu, les onglets Rôles, Personnes et Matrice montrent l’état ; pour une personne, « Que peut faire cette personne ? » montre chaque droit avec son origine.',
