  'Prüfe die Angaben. Mit „Ändern“ springst du in den Schritt. Erst jetzt wird der Verein eingerichtet.':
    'Vérifie les informations. Avec « Modifier », tu sautes dans l’étape. Le club n’est configuré qu’à partir de maintenant.',
