  'Sportliche Leitung': 'Direction sportive',
  'Sportliche Leitung, Jugendleitung und Vorstand sehen im Reiter „Team“ eine Übersicht über die Abteilungen (Senioren, Frauen, Jugend) – ohne Zugriff in die einzelnen Mannschaften. Oben stehen die Kennzahlen, darunter eine Karte je Mannschaft mit Kader, Trainerteam, Trainingsbeteiligung der letzten 4 Wochen und dem nächsten Spiel. Die Ampel gilt nur für die Trainingsbeteiligung: gut ab 65 %, mittel 50–64 %, niedrig darunter; bei weniger als 3 erfassten Einheiten steht „zu wenig Daten“. Wer auch selbst in einer Mannschaft ist, schaltet oben zwischen „Meine Mannschaft“ und „Übersicht“ um.':
    'La direction sportive, la direction des jeunes et le comité directeur voient dans l’onglet « Équipe » un aperçu des sections (seniors, féminines, jeunes) – sans accès aux équipes individuelles. En haut figurent les indicateurs, en dessous une carte par équipe avec effectif, staff d’entraîneurs, participation aux entraînements des 4 dernières semaines et prochain match. Le feu tricolore ne concerne que la participation aux entraînements : bon à partir de 65 %, moyen 50–64 %, faible en dessous ; avec moins de 3 séances enregistrées, « trop peu de données » s’affiche. Qui est aussi lui-même dans une équipe bascule en haut entre « Mon équipe » et « Aperçu ».',
