  'Thema bearbeiten': 'Modifier le sujet',
  'Thema eröffnen': 'Ouvrir un sujet',
  Themen: 'Sujets',
  'Themen eröffnen Verantwortliche im Verein.': 'Les responsables du club ouvrent les sujets.',
  'Themen schließt das Moderationsteam.': 'L’équipe de modération ferme les sujets.',
  'Tipp: Ort in der Karten-App suchen, „Teilen“ wählen und den Link hier einfügen. Ohne Link nutzt „Route“ die eingetragene Adresse.':
    'Astuce : cherche le lieu dans l’app de cartes, choisis « Partager » et colle le lien ici. Sans lien, « Itinéraire » utilise l’adresse saisie.',
  'Tippe auf der Anmeldeseite auf „Passwort vergessen?“. Du bekommst einen Link per E-Mail, mit dem du ein neues Passwort festlegst. Im Konto kannst du es jederzeit ändern.':
    'Sur la page de connexion, touche « Mot de passe oublié ? ». Tu reçois un lien par e-mail pour définir un nouveau mot de passe. Dans le compte, tu peux le changer à tout moment.',
  'Tippe auf die Uhrzeit: Es öffnet sich ein Fenster mit zwei Drehwalzen wie bei einem Wecker – links die Stunde, rechts die Minute (in 5er-Schritten). Wische oder scrolle, bis die richtige Zeit in der Mitte steht, und tippe auf „Übernehmen“. Beim Anlegen eines Termins wählst du Beginn und Ende; die Dauer zeigt die App darunter.':
    'Touche l’heure : une fenêtre s’ouvre avec deux molettes comme sur un réveil – à gauche l’heure, à droite les minutes (par pas de 5). Balaye ou fais défiler jusqu’à ce que la bonne heure soit au centre, puis touche « Appliquer ». Lors de la création d’un événement, tu choisis début et fin ; l’app affiche la durée en dessous.',
  'Tippe auf einen Spieler, um seine Rückmeldung zu korrigieren.':
    'Touche un joueur pour corriger sa réponse.',
  'Tippe im Termin bei „Teilnehmer“ auf eine Person und wähle Zusage, Unsicher oder Absage. Das geht auch nach Ablauf der Frist (bis eine Woche nach Beginn).':
    'Dans l’événement, touche une personne sous « Participants » et choisis Confirmation, Incertain ou Désistement. Cela fonctionne aussi après l’expiration du délai (jusqu’à une semaine après le début).',
  'Tippe in „Mein Konto“ auf „Bezahlen / Zahlung melden“. Du siehst die Bezahlinfos der Mannschaft (IBAN zum Kopieren, PayPal, bar). Nach dem Bezahlen tippst du „Ich habe bezahlt“. Sobald die Kasse den Eingang bestätigt hat, ist dein Konto ausgeglichen.':
    'Dans « Mon compte », touche « Payer / déclarer un paiement ». Tu vois les infos de paiement de l’équipe (IBAN à copier, PayPal, espèces). Après avoir payé, touche « J’ai payé ». Dès que la caisse a confirmé la réception, ton compte est équilibré.',
  'Tippe oben rechts auf die Lupe und gib mindestens zwei Buchstaben ein. Du findest Termine, Mitglieder, News und Mannschaften. Personen siehst du nur, wenn du auch sonst ihr Profil sehen darfst (z. B. aus deiner Mannschaft oder deine Kinder).':
    'Touche la loupe en haut à droite et saisis au moins deux lettres. Tu trouves des événements, membres, actualités et équipes. Tu ne vois des personnes que si tu as aussi le droit de voir leur profil (p. ex. de ton équipe ou tes enfants).',
