    'Via ce lien, tu définis ton mot de passe (valable {0} jours) :',
  'Über Ich → Admin-Verwaltung oder Verein → Meine Vereinsaufgaben → Verwaltung erreichst du Mitglieder, Rollen und Module.':
    'Via Moi → Administration ou Club → Mes tâches de club → Administration, tu accèdes aux membres, rôles et modules.',
