  'Übliche Strafen als Vorlage – abwählen, was ihr nicht wollt. Beträge und weitere Strafen änderst du später.':
    'Amendes usuelles comme modèle – désélectionnez ce que vous ne voulez pas. Tu modifieras les montants et d’autres amendes plus tard.',
