  'Umlage: Gesamtbetrag auf gewählte Personen aufteilen oder festen Betrag je Person fordern. Beiträge: z. B. 5 € monatlich, die App bucht sie allen Spielern zum Fälligkeitstag. Getränke: Preis festlegen und je Person Striche zählen. Alle Betroffenen werden benachrichtigt.':
    'Répartition des frais : répartir le montant total entre les personnes choisies ou demander un montant fixe par personne. Cotisations : p. ex. 5 € par mois, l’app les enregistre pour tous les joueurs à la date d’échéance. Boissons : fixer le prix et compter les traits par personne. Toutes les personnes concernées sont notifiées.',
