  'Welche Beitragsarten gibt es? Mit Vorschlägen starten und Beträge anpassen.':
    'Quels types de cotisation existent ? Commence avec des suggestions et adapte les montants.',
  'Welche Daten habt ihr schon? Die Importe laufen nach der Einrichtung, jeweils mit Vorlage, Spaltenzuordnung und Vorschau. Excel-Dateien mit mehreren Blättern gehen auch – du wählst das Blatt aus.':
    'Quelles données avez-vous déjà ? Les imports se font après la configuration, chacun avec modèle, affectation des colonnes et aperçu. Les fichiers Excel à plusieurs feuilles fonctionnent aussi – tu choisis la feuille.',
  'Welche Daten wir verarbeiten': 'Quelles données nous traitons',
  'Welche Daten wir verarbeiten und warum': 'Quelles données nous traitons et pourquoi',
  'Welche Kasse?': 'Quelle caisse ?',
  'Welche Konten und Kassen gibt es?': 'Quels comptes et caisses existent ?',
  'Welche Meldungen bekomme ich und wie stelle ich sie ein?':
    'Quelles notifications puis-je recevoir et comment les régler ?',
  'Welche Vorlage passt?': 'Quel modèle convient ?',
  'Welcher Untergrund?': 'Quel revêtement ?',
  'Welches Mitglied welche Beitragsart zahlt (ab wann, optional mit abweichendem Betrag). Mitglieder werden über Mitgliedsnummer oder Namen erkannt.':
    'Quel membre paie quel type de cotisation (à partir de quand, éventuellement avec un montant différent). Les membres sont reconnus par numéro de membre ou nom.',
  'Wenige Themen, die nach Ablauf schließen – für Absprachen, Ideen und Rückmeldungen. Bitte freundlich bleiben; das Moderationsteam blendet Unpassendes aus.':
    'Quelques sujets qui se ferment à l’expiration – pour des accords, des idées et des retours. Merci de rester aimable ; l’équipe de modération masque ce qui est inapproprié.',
  'Wenige, moderierte Diskussionsthemen': 'Quelques sujets de discussion modérés',
  'Wenn dein Verein das Sponsoren-Modul nutzt, zeigt ein kleines Wischelement auf Start, im Team-Reiter und im Verein-Reiter bis zu drei Sponsoren, die der Verein als Werbung freigegeben hat. Es ist immer als „Anzeige“ gekennzeichnet und wechselt alle paar Sekunden von selbst; du kannst auch wischen. Ein Tipp öffnet die Seite des Sponsors. Alle Sponsoren findest du unter „Verein → Sponsoren“. Die App wertet nicht aus, wer was ansieht oder antippt. Manche Sponsoren stellt der Verein so ein, dass Jugendspieler sie nicht sehen.':
    'Si ton club utilise le module Sponsors, un petit élément à balayer sur l’accueil, dans l’onglet Équipe et dans l’onglet Club affiche jusqu’à trois sponsors que le club a autorisés comme publicité. Il est toujours signalé « Publicité » et change tout seul toutes les quelques secondes ; tu peux aussi balayer. Un toucher ouvre la page du sponsor. Tu trouves tous les sponsors sous « Club → Sponsors ». L’app n’analyse pas qui regarde ou touche quoi. Le club règle certains sponsors pour que les jeunes joueurs ne les voient pas.',
  'Wenn deine Rückmeldung (oder die deines Kindes) noch fehlt – so lange vor der Frist:':
    'Si ta réponse (ou celle de ton enfant) manque encore – combien de temps avant le délai :',
  'Wenn du das nicht warst, ignoriere diese E-Mail – dein Passwort bleibt unverändert.':
    'Si ce n’était pas toi, ignore cet e-mail – ton mot de passe reste inchangé.',
  'Wenn du dich nicht angemeldet hast, ändere bitte dein Passwort.':
    'Si tu ne t’es pas connecté, merci de changer ton mot de passe.',
  'Wenn eine Mannschaft für ein Spiel Spieler braucht, meldet das Trainerteam einen Bedarf. Andere Mannschaften können Spieler abstellen. Du siehst dann den Einsatz im Termin als „Gastspieler“.':
    'Lorsqu’une équipe a besoin de joueurs pour un match, le staff d’entraîneurs signale un besoin. D’autres équipes peuvent mettre des joueurs à disposition. Tu vois alors l’engagement dans l’événement comme « Joueur invité ».',
  'Wenn eine Zu- oder Absage noch fehlt': 'Si une confirmation ou un désistement manque encore',
  'Wenn eingeschaltet, brauchen alle mit Verwaltungsrechten (Vorstand, Admins, Jugendleitung …) die 2-Faktor-Anmeldung, bevor sie Mitgliederdaten bearbeiten können.':
    'Si activé, toutes les personnes avec des droits d’administration (comité directeur, admins, direction des jeunes …) ont besoin de la connexion à deux facteurs avant de pouvoir modifier des données de membres.',
